# Settle the selected claims together. Each that can be settled is settled (or goes PENDING) and
# audited as a single settle would be, in list order; each that cannot is left as it is. Answers
# how many of each.
validate:
  class: net.officefloor.hq.app.claim.ValidateBulkSettle
  next: settle
settle:
  class: net.officefloor.hq.app.claim.SettleClaims
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithBulkSettle
  govern: [ transaction ]
package net.officefloor.hq.app.claim;

import java.util.Set;

/** A validated bulk settle: the selected claims and who settles them. */
public record BulkSettle(Set<Long> claimIds, String user) {
}
package net.officefloor.hq.app.claim;

import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.period.ClosedPeriods;
import net.officefloor.hq.app.period.PeriodClosedException;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.Watches;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.Snapshot;
import net.officefloor.hq.app.settings.Settings;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.hq.app.voidreason.VoidReasons;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Settles each selected claim that can be settled, in list order (people in list order, each
 *  person's newest claim first), by the signed-in user. Each is settled as a single settle would
 *  be — its own audit line, then the figures it moved; one that goes PENDING counts as settled. One
 *  that cannot be settled (or is not on the sheet) is left as it is and counted as refused. The
 *  claims it settles carry the sheet's next batch number; one that settles none takes no number. */
public class SettleClaims {
    public void settle(@PathVariable("sheetId") String sheetId, @Val BulkSettle bulk, Claims claims, People people,
            ClaimNumbers numbers, Figures figures, ClosedPeriods closedPeriods, Settings settings, Rollup rollup,
            ClaimLog log, Sheets sheets, Watches watches, Audit audit, VoidReasons voidReasons, Out<BulkSettleResult> result) {
        ClaimStatusChange change = new ClaimStatusChange(ClaimAction.SETTLE, bulk.user());
        ApplyClaimStatus apply = new ApplyClaimStatus();
        RecordClaimStatusChanged record = new RecordClaimStatusChanged();
        List<Claim> all = claims.onSheet(sheetId);
        int settled = 0;
        int batch = claims.nextBatch(sheetId);
        for (Person person : people.onSheet(sheetId)) {
            for (Claim listed : all) {
                if (listed.getPersonId() != person.getId() || !bulk.claimIds().contains(listed.getId())) continue;
                Claim claim = claims.find(sheetId, listed.getId());
                Snapshot before = rollup.snapshot(sheetId);
                try {
                    apply.apply(change, claim, numbers, people, figures, closedPeriods, settings, log, sheets, voidReasons);
                } catch (ClaimStatusRefusedException | PeriodClosedException e) {
                    continue;
                }
                claim.setBatch(batch);
                claims.save(claim);
                record.record(change, claim, people, log, watches, audit);
                rollup.record(sheetId, before, bulk.user());
                settled++;
            }
        }
        result.set(new BulkSettleResult(settled, bulk.claimIds().size() - settled));
    }
}
package net.officefloor.hq.app.claim;

import java.util.LinkedHashSet;
import net.officefloor.hq.app.sheet.InvalidSheetRequestException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateBulkSettle {
    public void validate(@RequestBody BulkSettleRequest request, Out<BulkSettle> body) throws InvalidSheetRequestException {
        if (request == null || request.claimIds() == null || request.claimIds().isEmpty()) {
            throw new InvalidSheetRequestException("Select the claims to settle");
        }
        body.set(new BulkSettle(new LinkedHashSet<>(request.claimIds()), request.user()));
    }
}
package net.officefloor.hq.app.claim;

/** How many of the selected claims a bulk settle settled (a claim gone PENDING counts), and how many it refused. */
public record BulkSettleResult(int settled, int refused) {
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithBulkSettle {
    public void respond(@Val BulkSettleResult result, ObjectResponse<BulkSettleResult> response) {
        response.send(result);
    }
}

